mapper.select:
SELECT account_id, bank_code, account_number_enc, account_name, balance,
       account_type, is_active, synced_at
FROM bank_accounts
WHERE user_id = #{userId, jdbcType=CHAR}
  AND account_id = #{accountId, jdbcType=CHAR}
  AND is_active = TRUE

